  if(action==='block'){await loadCatalog();modal('Bloquear horário',`<div class="stack">${select('Profissional','professional_id',pageData.professionals.filter(p=>session.user.role!=='professional'||p.id===session.user.professional_id).map(p=>({value:p.id,label:p.name})))}${field('Data','date','date',pageData.date||localDate(),'required')}${field('Início','start','time','09:00','required')}${field('Fim','end','time','10:00','required')}${field('Motivo','reason','text','','required')}</div>`,'block');}
  if(action==='blocks'){const blocks=await api('/blocks');modal('Bloqueios da agenda',blocks.map(b=>`<div class="integration"><div>${dateTime(b.starts_at)} → ${hour(b.ends_at)}<p>${e(b.reason)}</p></div>${button('Remover','remove-block',`data-id="${b.id}"`,'small danger')}</div>`).join('')||empty('Nenhum bloqueio.'));}
  if(action==='remove-block'){await api(`/blocks/${id}`,{method:'DELETE',body:{}});dialog.close();return toast('Bloqueio removido.');}
  if(action==='waitlist'){await loadCatalog();const [customers,rows]=await Promise.all([api('/customers'),api('/waitlist')]);modal('Lista de espera',`<form data-form="waitlist" class="stack">${select('Cliente','customer_id',customers.map(c=>({value:c.id,label:c.name})))}${select('Serviço','service_id',pageData.services.map(s=>({value:s.id,label:s.name})))}${field('Data','date','date',localDate(),'required')}<p data-error class="error"></p><button class="btn primary" type="submit">Adicionar à lista</button></form><br>${rows.map(w=>`<div class="integration"><span>${e(nameOf(customers,w.customer_id))} · ${w.date}</span>${pill(w.status)}</div>`).join('')}`);}
  if(action==='refund')return modal('Estornar sinal',`<p>O valor integral será devolvido pelo provedor. Esta ação financeira é auditada.</p>${button('Confirmar estorno integral','confirm-refund',`data-id="${id}"`,'danger')}`);
