  if(action==='audit'){const rows=await api('/audit');modal('Trilha de auditoria',`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Evento</th><th>Ator</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${dateTime(r.at)}</td><td>${e(r.action)}</td><td>${e(r.actor.slice(0,12))}</td></tr>`).join('')}</tbody></table></div>`);}
  if(action==='export')return download(await api('/export'),'agendazap-export.json');
  if(action==='export-customer')return download(await api(`/customers/${id}/export`),'cliente.json');
