  if(action==='confirm-anonymize'){await api(`/customers/${id}/anonymize`,{method:'POST',body:{}});dialog.close();toast('Projeção anonimizada.');return route();}
  if(action==='billing-checkout'){const planId=node.dataset.plan;if(!planId)return toast('Selecione um plano.');await api('/billing/checkout',{method:'POST',body:{plan_id:planId}});toast('Link de assinatura preparado. Confira o plano no provedor.');return route();}
  if(action==='billing-cancel')return modal('Cancelar assinatura da plataforma',`<p>A assinatura será cancelada no Mercado Pago. Confira sua política de acesso com o administrador.</p>${button('Confirmar cancelamento','confirm-billing-cancel','','danger')}`);
  if(action==='confirm-billing-cancel'){await api('/billing/cancel',{method:'POST',body:{}});dialog.close();toast('Assinatura cancelada.');return route();}
  if(action==='users'){await loadCatalog();const users=await api('/users');modal('Equipe e acessos',`<div class="stack">${users.map(u=>`<div class="flex between"><div><b>${e(u.name)}</b><p class="note">${e(u.email)} · ${e(u.role)} · ${u.active?'ativo':'desativado'}</p></div>${u.role!=='owner'&&u.active?button('Desativar','disable-user',`data-id="${u.id}"`,'small danger'):''}</div>`).join('')}<h3>Novo acesso</h3><form data-form="user" class="stack">${field('Nome','name','text','','required')}${field('E-mail','email','email','','required')}${field('Senha inicial','password','password','','required minlength="12"')}${select('Perfil','role',[{value:'attendant',label:'Atendente'},{value:'manager',label:'Gerente'},{value:'professional',label:'Profissional'}])}${select('Profissional (para perfil profissional)','professional_id',[{value:'',label:'Nenhum'},...pageData.professionals.map(p=>({value:p.id,label:p.name}))])}<p data-error class="error"></p><button type="submit" class="btn primary">Criar acesso</button></form></div>`);}
  if(action==='disable-user'){await api(`/users/${id}/disable`,{method:'POST',body:{}});dialog.close();toast('Acesso desativado.');}
  if(action==='choose-service'){const s=bookingState.catalog.services.find(s=>s.id===id);if(s.deposit_cents&&!bookingState.catalog.pix_enabled)return toast('Este serviço precisa de PIX; fale com o estabelecimento.');bookingState.service_id=id;bookingState.step=2;delete bookingState.slots;return renderBooking();}
  if(action==='choose-slot'){bookingState.slot=bookingState.slots[Number(node.dataset.index)];bookingState.step=3;bookingState.idempotency_key=crypto.randomUUID();return renderBooking();}
