  if(action==='public-reschedule')modal('Escolher uma nova data',`<div class="stack">${field('Nova data','date','date',localDate(pageData.manage.catalog.tenant.timezone),'required')}</div>`,'public-reschedule-slots');
  if(action==='public-reschedule-slot'){const m=pageData.manage,slot=pageData.rescheduleSlots[Number(node.dataset.index)];await api(`/public/appointments/${m.id}/reschedule`,{method:'POST',body:{starts_at:slot.starts_at,professional_id:slot.professional_id},token:m.token});dialog.close();toast('Horário alterado.');return route();}
