function download(data,name) {const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function toUTC(date,time,tz) {const target=Date.parse(date+'T'+time+':00Z');let guess=target;for(let i=0;i<3;i++){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(guess)).map(p=>[p.type,p.value]));guess+=target-Date.parse(`${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}:00Z`);}return new Date(guess).toISOString();}
async function submit(form) {
  const type=form.dataset.form,f=new FormData(form),data=Object.fromEntries(f.entries());
  if(type==='login'||type==='register'){session=await api(`/auth/${type}`,{method:'POST',body:data});pageData={};location.hash='app/dashboard';return;}
  if(type==='service'){const body={name:data.name,duration_minutes:Number(data.duration_minutes),price_cents:Math.round(Number(data.price)*100),deposit_cents:Math.round(Number(data.deposit)*100),active:f.has('active')};await api(`/services${pageData.editId?'/'+pageData.editId:''}`,{method:pageData.editId?'PATCH':'POST',body});}
  if(type==='professional'){const availability=[];for(let i=0;i<7;i++)if(f.has('day_'+i))availability.push({weekday:i,start:data['start_'+i],end:data['end_'+i]});await api(`/professionals${pageData.editId?'/'+pageData.editId:''}`,{method:pageData.editId?'PATCH':'POST',body:{name:data.name,active:f.has('active'),service_ids:f.getAll('service_ids'),availability}});}
  if(type==='customer'){const body={name:data.name,phone:data.phone,consent:f.has('consent'),...(pageData.editId?{tags:data.tags.split(';').map(x=>x.trim()).filter(Boolean)}:{})};await api(`/customers${pageData.editId?'/'+pageData.editId:''}`,{method:pageData.editId?'PATCH':'POST',body});}
  if(type==='operator-slots') {pageData.bookingService=data.service_id;pageData.operatorSlots=await api(`/availability?service_id=${data.service_id}&date=${data.date}&professional_id=${data.professional_id}`);dialog.close();return modal('Escolha o horário',`<div class="slot-grid">${pageData.operatorSlots.map((s,i)=>`<button class="slot" data-action="operator-slot" data-index="${i}">${s.time}<span>${e(s.professional_name)}</span></button>`).join('')}</div>${pageData.operatorSlots.length?'':empty('Nenhum horário nesta data.')}`);}
  if(type==='operator-book'){await api('/appointments',{method:'POST',body:{name:data.name,phone:data.phone,consent:f.has('consent'),service_id:pageData.bookingService,professional_id:pageData.slot.professional_id,starts_at:pageData.slot.starts_at,idempotency_key:crypto.randomUUID()}});}
  if(type==='reschedule-slots') {const a=pageData.appointments.find(a=>a.id===pageData.editId);pageData.rescheduleSlots=await api(`/availability?service_id=${a.service_id}&date=${data.date}&professional_id=${data.professional_id}`);dialog.close();return modal('Escolha o novo horário',`<div class="slot-grid">${pageData.rescheduleSlots.map((s,i)=>`<button class="slot" data-action="reschedule-slot" data-index="${i}">${s.time}<span>${e(s.professional_name)}</span></button>`).join('')}</div>${pageData.rescheduleSlots.length?'':empty('Nenhum horário livre.')}`);}
  if(type==='block'){await api('/blocks',{method:'POST',body:{professional_id:data.professional_id,starts_at:toUTC(data.date,data.start,session.tenant.timezone),ends_at:toUTC(data.date,data.end,session.tenant.timezone),reason:data.reason}});}
  if(type==='waitlist'){await api('/waitlist',{method:'POST',body:data});dialog.close();return toast('Cliente adicionado à lista.');}
  if(type==='settings'){const body={...data};for(const key of ['min_notice_minutes','horizon_days','buffer_minutes','cancellation_hours','recovery_days'])body[key]=Number(body[key]);session.tenant=await api('/settings',{method:'PATCH',body});}
  if(type==='simulate'){const result=await api('/conversations/simulate',{method:'POST',body:data});dialog.close();toast(result.reply||'Conversa em atendimento humano.');return route();}
  if(type==='reply'){await api(`/conversations/${selectedConversation}/reply`,{method:'POST',body:data});return route();}
  if(type==='link-whatsapp'){await api('/settings/whatsapp',{method:'PATCH',body:data});}
  if(type==='password'){await api('/auth/password',{method:'POST',body:data});dialog.close();session=null;toast('Senha alterada. Entre novamente.');location.hash='login';return;}
  if(type==='user'){await api('/users',{method:'POST',body:{...data,professional_id:data.professional_id||null}});dialog.close();return toast('Acesso criado.');}
  if(type==='find-slots'){bookingState.date=data.date;bookingState.professional_id=data.professional_id;bookingState.slots=await api(`/public/${bookingState.slug}/availability?service_id=${bookingState.service_id}&date=${data.date}&professional_id=${data.professional_id}`);return renderBooking();}
  if(type==='public-book'){const b=bookingState;const result=await api(`/public/${b.slug}/appointments`,{method:'POST',body:{name:data.name,phone:data.phone,consent:f.has('consent'),service_id:b.service_id,professional_id:b.slot.professional_id,starts_at:b.slot.starts_at,idempotency_key:b.idempotency_key,...(b.campaign_id?{campaign_id:b.campaign_id}:{})}});bookingState={};location.hash=`manage/${result.appointment.id}/${result.manage_token}`;return;}
  if(type==='payment-email'){const m=pageData.manage;await api(`/public/appointments/${m.id}/payment-email`,{method:'POST',body:data,token:m.token});toast('E-mail recebido. Aguarde alguns segundos e atualize o pagamento.');return route();}
  if(type==='public-reschedule-slots'){const m=pageData.manage;pageData.rescheduleSlots=await api(`/public/${m.catalog.tenant.slug}/availability?service_id=${m.appointment.service_id}&date=${data.date}`);dialog.close();return modal('Escolha o novo horário',`<div class="slot-grid">${pageData.rescheduleSlots.map((s,i)=>`<button class="slot" data-action="public-reschedule-slot" data-index="${i}">${s.time}<span>${e(s.professional_name)}</span></button>`).join('')}</div>${pageData.rescheduleSlots.length?'':empty('Nenhum horário livre.')}`);}
  dialog.close();toast('Salvo.');return route();
}
document.addEventListener('click',async event=>{const node=event.target.closest('[data-action]');if(!node||node.disabled)return;event.preventDefault();node.disabled=true;try{await action(node.dataset.action,node);}catch(error){toast(error.message);}finally{node.disabled=false;}});
document.addEventListener('submit',async event=>{const form=event.target.closest('[data-form]');if(!form)return;event.preventDefault();if(busy)return;busy=true;const btn=form.querySelector('[type=submit]');if(btn)btn.disabled=true;try{await submit(form);}catch(error){const node=form.querySelector('[data-error]');if(node)node.textContent=error.message;else toast(error.message);}finally{busy=false;if(btn)btn.disabled=false;}});
document.addEventListener('change',event=>{if(event.target.id==='dashboard-date'){pageData.date=event.target.value;route();}});
document.addEventListener('input',event=>{if(event.target.id==='customer-search'){pageData.customerQuery=event.target.value;pageData.customerPage=1;clearTimeout(customerSearchTimer);customerSearchTimer=setTimeout(()=>loadPage('customers'),300);}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){if(dialog?.open)dialog.close();setMobileMenu(false);}});
window.addEventListener('hashchange',route);
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
route();
